export function fileIconKind(name = '', languageId) {
  const filename = String(name).replace(/\\/g, '/').split('/').pop().toLowerCase();
  if (Object.hasOwn(FILE_NAMES, filename)) return FILE_NAMES[filename];
  if (Object.hasOwn(PROJECT_FILES, filename)) return PROJECT_FILES[filename];
  if (/^tsconfig(?:\.[^.]+)*\.json$/.test(filename)) return '_tsconfig';
  if (/^jsconfig(?:\.[^.]+)*\.json$/.test(filename)) return '_javascript_2';
  if (/^vite\.config(?:\.[^.]+)*\.[cm]?[jt]s$/.test(filename)) return '_vite';
  if (/^webpack(?:\.[^.]+)*\.[cm]?[jt]s$/.test(filename)) return '_webpack';
  if (/^rollup\.config(?:\.[^.]+)*\.[cm]?[jt]s$/.test(filename)) return '_rollup';
  if (/^(?:eslint\.config(?:\.[^.]+)*\.[cm]?[jt]s|\.eslintrc(?:\.[cm]?js|\.json|\.ya?ml)?|\.eslintignore)$/.test(filename)) return '_eslint';
  if (/^(?:prettier\.config(?:\.[^.]+)*\.[cm]?[jt]s|\.prettierrc(?:\.[cm]?[jt]s|\.json5?|\.ya?ml|\.toml)?|\.prettierignore|tailwind\.config(?:\.[^.]+)*\.[cm]?[jt]s|postcss\.config\.[cm]?[jt]s|\.postcssrc(?:\.[cm]?js|\.json|\.ya?ml)?)$/.test(filename)) return '_config';
  if (/^(?:babel\.config\.[cm]?[jt]s|\.babelrc(?:\.[cm]?js|\.json)?)$/.test(filename)) return '_babel';
  if (/^(?:vitest|jest|playwright|cypress)\.config(?:\.[^.]+)*\.[cm]?[jt]s$/.test(filename)) return '_javascript_1';
  if (/^(?:readme|contributing)(?:\.[^.]+)*$/.test(filename)) return '_info';
  if (/^changelog(?:\.[^.]+)*$/.test(filename)) return '_clock';
  if (/^(?:licen[cs]e|copying|notice)(?:\.[^.]+)*$/.test(filename)) return '_license';
  if (/^(?:dockerfile(?:\.[^.]+)*|(?:[^.]+\.)+dockerfile|(?:docker-)?compose(?:\.[^.]+)*\.ya?ml)$/.test(filename)) return '_docker';
  if (/^\.env(?:\.[^.]+)*$/.test(filename)) return '_config';
  // Walk suffixes from longest to shortest: app.test.ts must beat plain .ts.
  for (let dot = filename.indexOf('.'); dot >= 0; dot = filename.indexOf('.', dot + 1)) {
    const extension = filename.slice(dot + 1);
    if (Object.hasOwn(FILE_EXTENSIONS, extension)) return FILE_EXTENSIONS[extension];
  }
  if (filename.endsWith('.lock')) return '_lock';
  return languageId && Object.hasOwn(LANGUAGE_IDS, languageId) ? LANGUAGE_IDS[languageId] : '_default';
}

export function resolveFileIcon(name, languageId) {
  const kind = fileIconKind(name, languageId);
  const definition = DEFINITIONS[kind] ?? DEFINITIONS._default;
  return { kind, tone: definition.tone, ...GLYPHS[definition.glyph] };
}
